-- Banda 1–2, S13–S14: înlocuiește textele celor 56 activități cu varianta în trepte.
-- Cere întâi 20261117102924_stoc_materiale.sql (coloana materiale.produs_cheie).
-- 1. Copiază cele 56 rânduri, exact cum sunt, în backup_20261117_b12_s13s14.
-- 2. UPDATE pe id + banda 1–2, numai dacă titlul, pașii, nota, materialele,
--    durata și „gata când” sunt cele din backup-ul din 17.11.2026 (sha256 5c9039d9…2076).
--    Orice nepotrivire oprește migrarea; totul e o singură tranzacție.
-- 3. Oprește-se dacă vreuna dintre activități are deja bife (completions), doar citire.
-- 4. Adaugă materialele 1–2 (id-uri b12-), legăturile și textul „gratuit” pe săptămână.
-- Nu schimbă zi, pilon, mod_default, tema, id-uri; nu atinge completions, children,
-- day_notes, archive_days sau stocarea. A doua rulare nu schimbă nimic.
-- Nu se aplică pe Familie din acest PR.

do $b12$
declare
  plan record;
  cur record;
  updated_count int := 0;
  skipped_count int := 0;
  touched int;
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'activities' and column_name = 'pas_in_plus'
  ) then
    raise exception 'B12 S13–S14: lipsește coloana activities.pas_in_plus.';
  end if;
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'materiale' and column_name = 'produs_cheie'
  ) then
    raise exception 'B12 S13–S14: lipsește materiale.produs_cheie. Aplică întâi 20261117102924_stoc_materiale.sql.';
  end if;

  create temporary table b12_plan (
    id text primary key,
    old_titlu text not null,
    old_pasi text[] not null,
    old_nota text,
    old_materiale text[] not null,
    old_durata integer not null,
    old_gata text not null,
    titlu text not null,
    materiale text[] not null,
    durata_min integer not null,
    pasi text[] not null,
    gata_cand text not null,
    pas_in_plus text not null,
    provocare text not null,
    siguranta text
  ) on commit drop;

  insert into b12_plan values
    ($q$s13-2-3-z1-fizic$q$, $q$Haina pe umeri pe scurt$q$, array[$q$Luați haina împreună.$q$, $q$Puneți-o pe umeri 10–20 de secunde: „Haină. Cald.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$haină$q$]::text[], 5, $q$A ținut sau a simțit haina pe umeri.$q$, $q$Haina pe umeri, mâna prin mânecă$q$, array[$q$haina lui de afară$q$]::text[], 6, array[$q$Întindeți haina pe jos, cu gulerul spre el: „Haina ta.”$q$, $q$Puneți-i-o pe umeri și țineți mâneca deschisă.$q$, $q$Împinge el mâna prin mânecă până iese palma: „Cucu, mâna!”$q$, $q$La scos, trage el de mânecă, iar voi țineți haina.$q$]::text[], $q$A împins o mână prin mânecă până i-a ieșit palma.$q$, $q$Ambele mâini, una după alta, apoi scoate singur o mânecă.$q$, $q$Trucul cu haina pe jos: gulerul la picioarele lui, mâinile în mâneci, haina dată peste cap. Arătați o dată; orice încercare e bună.$q$, $q$Haina fără șnururi lungi la glugă. Nu închideți fermoarul până sub bărbie în joacă.$q$),
    ($q$s13-2-3-z1-mental$q$, $q$Arătăm haina de afară$q$, array[$q$Arătați haina: „Haină. Afară.”$q$, $q$Atingeți mâneca împreună pe scurt.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$haină$q$]::text[], 3, $q$A privit sau a atins haina.$q$, $q$Haina de afară și bluza de casă$q$, array[$q$haina lui de afară$q$, $q$o bluză subțire de casă$q$]::text[], 5, array[$q$Puneți-le alături: „Haina de afară. Bluza de casă.”$q$, $q$Atingeți-le pe rând: „Haina e groasă și caldă. Bluza e subțire.”$q$, $q$La fereastră: „Afară e frig. Adu-mi haina de afară.”$q$, $q$Așteptați 5–10 secunde să o aducă sau să o arate.$q$]::text[], $q$A adus sau a arătat haina de afară când i-ați cerut-o.$q$, $q$Instrucțiune în doi pași: „Ia haina și pune-o lângă ușă.”$q$, $q$Îmbrăcați voi ursulețul cu bluza subțire „pentru afară” și așteptați: protestează sau aduce haina?$q$, null),
    ($q$s13-2-3-z1-resurse$q$, $q$Haina pe cârlig$q$, array[$q$Duceți haina la cârlig împreună.$q$, $q$„La loc. Pe cârlig.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$haină$q$, $q$cârlig$q$]::text[], 4, $q$A ajutat să pună haina la loc.$q$, $q$Haina pe scaunul de la ușă$q$, array[$q$haina lui$q$, $q$scaunul de la ușă$q$]::text[], 5, array[$q$După ce scoateți haina, i-o întindeți: „Duci haina la ușă?”$q$, $q$Merge el cu haina până la scaunul de lângă ușă.$q$, $q$O lasă pe scaun, cum iese.$q$, $q$„La loc. Haina stă la ușă.” Bateți palma.$q$]::text[], $q$A dus haina până la scaun și a lăsat-o acolo.$q$, $q$O împăturiți împreună pe jumătate înainte s-o pună pe scaun.$q$, $q$A doua zi întrebați doar „Unde stă haina?” și vedeți dacă merge singur la scaun.$q$, $q$Scaunul stă pe podea, nu se cațără pe el. Dacă e un scaun de adult, haina o puneți pe șezut, nu pe spătar.$q$),
    ($q$s13-2-3-z1-social$q$, $q$Arătăm haina mamei / tatei$q$, array[$q$Duceți-l la adult cu haina: „Uite haina.”$q$, $q$Stați 1 minut, fără grabă.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$haină$q$]::text[], 3, $q$A participat la arătat.$q$, $q$Haina mamei, haina tatei$q$, array[$q$haina mamei sau a tatei$q$]::text[], 5, array[$q$Luați haina unui părinte: „A cui e?”$q$, $q$Duce el haina la părintele acela; dacă e grea, o târăște.$q$, $q$Părintele întinde brațul: „Mă ajuți? Mâneca.” El ține mâneca.$q$, $q$„Mulțumesc!” Bateți palma sau îmbrățișați-vă.$q$]::text[], $q$A dus haina la părintele potrivit și a ținut mâneca o clipă.$q$, $q$Două haine, doi oameni: a mamei la mama, a tatei la tata.$q$, $q$Dați voi „din greșeală” haina tatei la mama: o mută el la tata sau arată spre el?$q$, null),
    ($q$s13-2-3-z2-fizic$q$, $q$Șosetele pe picioare$q$, array[$q$Așezați-vă pe jos. Luați o șosetă.$q$, $q$Trageți-o pe picior împreună: „Șosetă.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$pereche de șosete$q$]::text[], 5, $q$A ajutat la o șosetă sau a privit.$q$, $q$Șosetele pe picioare$q$, array[$q$2 perechi de șosete: ale lui și ale voastre$q$]::text[], 7, array[$q$Așezați-vă pe jos, față în față.$q$, $q$Trageți-i șoseta pe degete până la jumătatea tălpii: „Tragi tu?”$q$, $q$Trage el de margine în sus; ajutați doar la călcâi.$q$, $q$„Gata!” Arată el piciorul îmbrăcat.$q$]::text[], $q$A tras singur șoseta de la jumătatea tălpii până sus, măcar o dată.$q$, $q$O scoate singur, trăgând de vârf, apoi încearcă a doua.$q$, $q$Din 4 șosete amestecate o găsește pe a lui (cea mică) și v-o dă pe a voastră.$q$, $q$Fără șosete cu buline antiderapante care se desprind. Nu stă în picioare pe pat sau pe canapea.$q$),
    ($q$s13-2-3-z2-mental$q$, $q$Șosetă și picior$q$, array[$q$Arătați piciorul: „Picior.”$q$, $q$Arătați șoseta: „Șosetă.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$șosetă$q$]::text[], 3, $q$A auzit și a văzut ambele.$q$, $q$Perechea de șosete$q$, array[$q$coșul cu perechi: 3 perechi de șosete ale lui, în culori diferite$q$]::text[], 8, array[$q$Răsturnați coșul cu cele 3 perechi.$q$, $q$Luați o șosetă: „Unde e una la fel?”$q$, $q$Așteptați; dacă nu o găsește, puneți două alături și întrebați „La fel?”$q$, $q$Puneți perechea împreună: „Pereche!” El o pune în coș.$q$]::text[], $q$A găsit singur șoseta la fel pentru cel puțin o pereche.$q$, $q$Potrivește toate cele 3 perechi.$q$, $q$Adăugați două șosete mari ale tatei: le pune deoparte sau le duce la tata.$q$, null),
    ($q$s13-2-3-z2-resurse$q$, $q$Șosetele în sertar$q$, array[$q$Deschideți sertarul împreună.$q$, $q$Puneți șosetele: „La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$șosete$q$]::text[], 4, $q$A ajutat cu șosetele în sertar.$q$, $q$Șosetele în sertar$q$, array[$q$șosetele lui$q$, $q$sertarul de jos$q$]::text[], 5, array[$q$Deschideți împreună sertarul de jos: „Aici stau șosetele.”$q$, $q$Îi dați perechile una câte una.$q$, $q$Le pune el în sertar.$q$, $q$Închideți sertarul încet, împreună: „Gata, la loc.”$q$]::text[], $q$A pus cel puțin două perechi în sertar.$q$, $q$Duce el perechile din coș până la sertar, 2–3 metri.$q$, $q$În sertar sunt și bluze: îl întrebați „Unde stau șosetele?” și le pune în colțul lor.$q$, $q$Țineți mâna pe sertar la închis, ca să nu-și prindă degetele. Sertarul nu se trage până iese din șine.$q$),
    ($q$s13-2-3-z2-social$q$, $q$Ajutăm la șosetă pe rând$q$, array[$q$Voi țineți șoseta. „Acum tu.”$q$, $q$Așteptați fără grabă dacă vrea să tragă.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$șosetă$q$]::text[], 3, $q$A încercat sau a privit ajutorul.$q$, $q$Șoseta pe rând: eu, apoi tu$q$, array[$q$o pereche de șosete ale lui și una a voastră$q$]::text[], 5, array[$q$Stați amândoi pe jos, desculți.$q$, $q$Trageți voi o șosetă: „Eu.”$q$, $q$Îi dați lui una: „Acum tu.” Ajutați la călcâi.$q$, $q$Arătați picioarele: „Amândoi cu șosete!”$q$]::text[], $q$A așteptat rândul lui și a tras sau a ținut șoseta.$q$, $q$Vă dă el șoseta potrivită, pe cea mare.$q$, $q$Vă ajută el: trage șoseta pe piciorul vostru.$q$, null),
    ($q$s13-2-3-z3-fizic$q$, $q$Papucii la ușă$q$, array[$q$Mergeți la ușă cu papucii.$q$, $q$Puneți piciorul în papuc: „Papuc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$papuci$q$]::text[], 4, $q$A pus un picior în papuc sau a încercat.$q$, $q$Papucii în picioare$q$, array[$q$papucii lui$q$]::text[], 5, array[$q$Mergeți împreună la papuci.$q$, $q$Țineți papucul deschis cu degetele în spate: „Piciorul înăuntru.”$q$, $q$Împinge el piciorul, sprijinit de voi sau de perete.$q$, $q$Face câțiva pași în papuci: „Papucii merg!”$q$]::text[], $q$A băgat piciorul în papucul ținut de voi și a mers câțiva pași.$q$, $q$Al doilea papuc, apoi îi scoate singur.$q$, $q$Din trei perechi (a lui, a mamei, a tatei) își alege papucii lui și îi încalță.$q$, $q$Se încalță stând pe jos sau sprijinit, nu în picioare pe treaptă.$q$),
    ($q$s13-2-3-z3-mental$q$, $q$Papuc sau pantof?$q$, array[$q$Arătați pe rând: „Papuc. Pantof.”$q$, $q$Atingeți ambele pe scurt.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$papuc$q$, $q$pantof$q$]::text[], 3, $q$A privit ambele încălțări.$q$, $q$Papuc sau cizmă?$q$, array[$q$papucii lui$q$, $q$cizmele sau ghetele lui$q$]::text[], 5, array[$q$Puneți-le alături: „Papucul e pentru casă. Cizma e pentru afară.”$q$, $q$Atingeți tălpile: cizma e tare, papucul e moale.$q$, $q$La ușă: „Ieșim afară. Ce încălțăm?”$q$, $q$Alege el; dacă ia papucul, spuneți blând: „Papucul e de casă. Afară luăm cizma.”$q$]::text[], $q$A ales cizma pentru afară, arătând-o sau aducând-o, măcar o dată.$q$, $q$Aceeași alegere pentru voi: papucii sau pantofii voștri?$q$, $q$Ascundeți o cizmă sub pernă cât se uită: „Unde e cizma?” O caută.$q$, null),
    ($q$s13-2-3-z3-resurse$q$, $q$Papucii la loc lângă ușă$q$, array[$q$Așezați papucii lângă ușă împreună.$q$, $q$„La loc. La ușă.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$papuci$q$]::text[], 4, $q$A ajutat să așeze papucii.$q$, $q$Încălțările pe preș$q$, array[$q$papucii și cizmele lui$q$, $q$preșul de la ușă$q$]::text[], 5, array[$q$„Unde stau papucii?” Mergeți la ușă.$q$, $q$Duce el papucii pe preș.$q$, $q$Îi așezați împreună, unul lângă altul.$q$, $q$„La loc. Papucii dorm la ușă.”$q$]::text[], $q$A dus papucii pe preș și i-a lăsat acolo, unul lângă altul sau aproape.$q$, $q$Duce și cizmele.$q$, $q$Pune papucii lui lângă perechea mamei: cei mici lângă cei mari.$q$, null),
    ($q$s13-2-3-z3-social$q$, $q$Schimbăm papucii împreună$q$, array[$q$Țineți mâna la schimbare.$q$, $q$„Împreună. Papuci.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$papuci$q$]::text[], 3, $q$A schimbat sau a acceptat ajutor.$q$, $q$Schimbăm încălțările împreună$q$, array[$q$cizmele și papucii lui și ai voștri$q$]::text[], 5, array[$q$Când veniți de afară, vă așezați amândoi pe treapta joasă sau pe jos.$q$, $q$„Eu scot cizma. Tu?” Trage el de cizmă, după ce deschideți voi fermoarul.$q$, $q$Îi dați papucii lui, voi îi luați pe ai voștri.$q$, $q$„Gata amândoi!”$q$]::text[], $q$A tras de o cizmă sau v-a dat papucii.$q$, $q$Desface el ariciul de la cizmă.$q$, $q$Vă aduce el papucii voștri.$q$, $q$Pe treapta joasă stă așezat, nu în picioare; voi stați lângă el.$q$),
    ($q$s13-2-3-z4-fizic$q$, $q$Căciula pe cap pe scurt$q$, array[$q$Puneți căciula pe cap 5–10 secunde dacă vrea.$q$, $q$„Căciulă. Cap.” Scoateți-o blând.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$căciulă$q$]::text[], 4, $q$A simțit căciula sau a refuzat clar.$q$, $q$Căciula în oglindă$q$, array[$q$căciula lui$q$, $q$oglinda de pe ușa dulapului$q$]::text[], 5, array[$q$Stați în fața oglinzii.$q$, $q$Puneți-vă voi căciula pe cap: „Căciulă!”$q$, $q$Îi dați căciula lui: și-o pune el pe cap, cum iese.$q$, $q$Vă uitați amândoi în oglindă: „Cezar cu căciulă!”$q$]::text[], $q$Și-a pus căciula pe cap, măcar pe jumătate, sau v-a pus-o vouă.$q$, $q$O trage el în jos, peste urechi.$q$, $q$„Cui mai punem căciulă?” Alege el: ursulețul sau tata.$q$, $q$Pomponul și ciucurii bine cusuți, fără nimic care se poate rupe și înghiți. Oglinda e fixată și nu e din sticlă la nivelul lui.$q$),
    ($q$s13-2-3-z4-mental$q$, $q$Unde e căciula?$q$, array[$q$Puneți căciula la vedere pe scaun.$q$, $q$„Unde e căciula? Uite.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$căciulă$q$]::text[], 3, $q$A arătat sau a privit căciula.$q$, $q$Unde s-a ascuns căciula?$q$, array[$q$căciula lui$q$, $q$un prosop$q$, $q$două cutii sau castroane mari$q$]::text[], 8, array[$q$Arătați căciula, apoi o acoperiți cu prosopul cât se uită: „Unde e căciula?”$q$, $q$O descoperă el.$q$, $q$Acum cu două cutii: o ascundeți sub una, cât vă vede.$q$, $q$Ridică el cutia potrivită: „Ai găsit-o!”$q$]::text[], $q$A găsit căciula sub cutia potrivită de cel puțin 2 ori din 3.$q$, $q$Mutați cutiile între ele o singură dată, încet.$q$, $q$O duceți după ușă cât vă vede mergând, apoi vă întoarceți cu mâna goală: „Unde e?” Merge el s-o caute.$q$, $q$Castroane de plastic sau cutii, nu de sticlă ori porțelan. Prosopul nu rămâne peste capul lui.$q$),
    ($q$s13-2-3-z4-resurse$q$, $q$Căciula pe cârlig$q$, array[$q$Duceți căciula la cârlig.$q$, $q$„La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$căciulă$q$]::text[], 4, $q$A ajutat să agățe căciula.$q$, $q$Căciula în coșul de la ușă$q$, array[$q$căciula lui$q$, $q$coșul de la ușă$q$]::text[], 5, array[$q$Arătați coșul cu poza căciulii lipită pe el: „Aici stă căciula.”$q$, $q$După ce o scoateți, i-o dați lui.$q$, $q$O duce el și o pune în coș.$q$, $q$„La loc!” Arată el poza căciulii.$q$]::text[], $q$A pus căciula în coșul de la ușă.$q$, $q$Instrucțiune în doi pași: „Ia mănușile și pune-le lângă căciulă.”$q$, $q$Înainte de ieșire: „Adu-mi căciula.” O găsește în coș și o aduce.$q$, null),
    ($q$s13-2-3-z4-social$q$, $q$Arătăm căciula adultului$q$, array[$q$Arătați căciula: „Uite căciula.”$q$, $q$Stați pe scurt, fără forțare.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$căciulă$q$]::text[], 3, $q$A participat la arătat.$q$, $q$Căciuli pentru toată familia$q$, array[$q$căciula lui și căciulile părinților$q$]::text[], 5, array[$q$Puneți căciulile pe jos.$q$, $q$„A cui e cea mare?” O duce el la părinte.$q$, $q$Părintele se apleacă, iar el i-o pune pe cap.$q$, $q$Părintele i-o pune pe a lui: „Amândoi cu căciulă!”$q$]::text[], $q$A dus căciula la adultul potrivit și a încercat să i-o pună pe cap.$q$, $q$Împarte el toate trei căciulile: a lui, a mamei, a tatei.$q$, $q$Tata își pune căciula lui Cezar, prea mică: râde și v-o mută pe cea potrivită?$q$, null),
    ($q$s13-2-3-z5-fizic$q$, $q$Mănușile pe mâini$q$, array[$q$Probați o mănușă pe scurt dacă vrea.$q$, $q$„Mănușă. Mână.” Apoi scoateți-o.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$mănuși$q$]::text[], 5, $q$A simțit mănușa sau a privit.$q$, $q$Mâna intră în mănușă$q$, array[$q$mănușile lui cu un deget$q$]::text[], 5, array[$q$Țineți mănușa deschisă: „Mâna intră în casă!”$q$, $q$Împinge el mâna; la degetul mare ajutați voi.$q$, $q$Bate din palme cu mănușa: „Bum, bum!”$q$, $q$O scoate el, trăgând de vârf cu cealaltă mână.$q$]::text[], $q$A împins mâna în mănușă până la încheietură.$q$, $q$Și a doua mănușă.$q$, $q$Cu mănușile pe mâini, ia o minge moale și o aruncă în coș.$q$, $q$Mănuși fără șnur între ele (nu le treceți pe după gât) și fără piese mici cusute.$q$),
    ($q$s13-2-3-z5-mental$q$, $q$Mână cu mănușă, mână fără$q$, array[$q$Arătați mâna cu mănușă: „Cu mănușă.”$q$, $q$Arătați mâna goală: „Fără.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$mănușă$q$]::text[], 3, $q$A văzut diferența pe scurt.$q$, $q$Perechea de mănuși$q$, array[$q$coșul cu perechi: mănușile lui și o pereche de mănuși de adult$q$]::text[], 6, array[$q$Puneți pe jos cele 4 mănuși, amestecate.$q$, $q$Luați una mică: „Unde e cealaltă? La fel.”$q$, $q$Caută el; dacă ezită, puneți două alături: „La fel?”$q$, $q$Perechea merge în coș: „Pereche!”$q$]::text[], $q$A potrivit o pereche de mănuși.$q$, $q$Ambele perechi: mică cu mică, mare cu mare.$q$, $q$Amestecați în coș și o lingură și o mașinuță: hainele într-o parte, ce nu e haină în alta.$q$, $q$Mașinuța e mare, fără roți sau piese care se desprind; lingura e de lemn sau de plastic.$q$),
    ($q$s13-2-3-z5-resurse$q$, $q$Mănușile în sertar$q$, array[$q$Puneți mănușile în sertar împreună.$q$, $q$„La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$mănuși$q$]::text[], 4, $q$A ajutat cu mănușile.$q$, $q$Mănușile lângă căciulă$q$, array[$q$mănușile lui$q$, $q$coșul de la ușă$q$]::text[], 5, array[$q$După ieșire, scoateți mănușile împreună.$q$, $q$„Unde stau mănușile?” Merge el la coșul de la ușă.$q$, $q$Le pune lângă căciulă.$q$, $q$Numărați pe degete: „Una, două. Pereche.”$q$]::text[], $q$A dus ambele mănuși în coș.$q$, $q$Le pune ținute împreună, ca pereche.$q$, $q$Înainte de ieșire, aduce singur din coș mănușile și căciula.$q$, null),
    ($q$s13-2-3-z5-social$q$, $q$Ținem mâna cu mănușa$q$, array[$q$Țineți mâna lui pe scurt, cu sau fără mănușă.$q$, $q$„Împreună.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$mănușă$q$]::text[], 3, $q$A ținut mâna sau a privit.$q$, $q$Ținem mâna cu mănușa$q$, array[$q$mănușile lui și ale voastre$q$]::text[], 5, array[$q$Puneți-vă amândoi mănușile.$q$, $q$Bateți palma: „Bate, mănușă!”$q$, $q$Țineți-vă de mână și mergeți câțiva pași prin casă.$q$, $q$„Cu mănuși ne e cald.”$q$]::text[], $q$A bătut palma cu mănușa sau a mers ținându-vă de mână.$q$, $q$Jocul „Unde e mâna?”: mâna se ascunde în mănușă și iese.$q$, $q$Vă pune el mănușa pe mână, iar voi împingeți.$q$, null),
    ($q$s13-2-3-z6-fizic$q$, $q$Ieșim îmbrăcați$q$, array[$q$Îmbrăcați haina și ieșiți 1–2 minute.$q$, $q$„Haină. Afară. Cald.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$haină$q$]::text[], 6, $q$A ieșit scurt îmbrăcat.$q$, $q$Ieșim îmbrăcați în curte$q$, array[$q$haina, căciula, mănușile și cizmele lui$q$, $q$coșul de la ușă$q$]::text[], 10, array[$q$Aduce el din coș căciula și mănușile.$q$, $q$Vă îmbrăcați în ordine și spuneți ce urmează: „Întâi cizmele, apoi haina, apoi căciula.” El ajută la fiecare.$q$, $q$Ieșiți în curte 5–8 minute; atingeți ceva rece, o bancă sau o frunză udă: „Rece! Bine că avem mănuși.”$q$, $q$La ușă: „Intrăm la cald.”$q$]::text[], $q$A ajutat la cel puțin două piese și a stat afară îmbrăcat câteva minute.$q$, $q$Alege el ce piesă urmează, dintre două pe care i le arătați.$q$, $q$Îmbracă el ursulețul cu o căciulă veche și îl ia afară.$q$, $q$E frig: ieșire de 5–10 minute, verificați des mâinile și nasul. Poarta curții rămâne închisă. Fără fular lung la gât; un fular scurt se bagă în haină.$q$),
    ($q$s13-2-3-z6-mental$q$, $q$Afară cu haină, înăuntru fără$q$, array[$q$La ușă cu haina: „Afară. Haină.”$q$, $q$Intrați și scoateți: „Înăuntru.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$haină$q$]::text[], 3, $q$A trecut pragul cu haina.$q$, $q$Ce purtăm afară azi?$q$, array[$q$cartonașele cu vremea: soare, ploaie, frig$q$, $q$căciula și mănușile lui$q$]::text[], 5, array[$q$La fereastră, numiți voi vremea: „Afară e frig.” sau „Plouă.”$q$, $q$Puneți jos cartonașul vremii de azi.$q$, $q$Lângă el aduce o haină adevărată potrivită: căciula sau mănușile.$q$, $q$„E frig, deci căciulă!”$q$]::text[], $q$A adus măcar o piesă potrivită lângă cartonașul vremii de azi.$q$, $q$Două cartonașe, frig și soare: pune căciula la frig.$q$, $q$Arătați cartonașul cu ploaia: alege el ce aduce (cizmele, haina cu glugă).$q$, $q$Cartonașele au colțurile rotunjite și sunt acoperite cu folie; dacă le mestecă, le luați, ca să nu rupă folia.$q$),
    ($q$s13-2-3-z6-resurse$q$, $q$Haina pe cârlig după afară$q$, array[$q$Agățați haina împreună după ieșire.$q$, $q$„La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$haină$q$]::text[], 4, $q$A ajutat la agățat.$q$, $q$Hainele la loc după afară$q$, array[$q$hainele lui de afară$q$, $q$coșul de la ușă$q$, $q$scaunul de la ușă$q$]::text[], 5, array[$q$La intrare, scoateți pe rând: mănușile, căciula, haina.$q$, $q$Duce el mănușile și căciula în coșul de la ușă.$q$, $q$Haina o duce pe scaunul de la ușă sau v-o dă vouă, ca s-o agățați sus.$q$, $q$„Totul la loc!”$q$]::text[], $q$A dus cel puțin două piese la locul lor: în coș sau pe scaun.$q$, $q$Duce și cizmele pe preș.$q$, $q$Lăsați o mănușă pe jos lângă ușă: „Lipsește ceva?” O găsește și o pune la loc.$q$, null),
    ($q$s13-2-3-z6-social$q$, $q$Intrăm împreună cu haina$q$, array[$q$Țineți mâna la intrare.$q$, $q$„Hai înăuntru. Scoatem haina.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A intrat cu adultul.$q$, $q$Intrăm împreună și ne încălzim$q$, array[$q$o pătură$q$]::text[], 5, array[$q$Intrați ținându-vă de mână.$q$, $q$Frecați-vă amândoi palmele: „Mâini reci. Frecăm.”$q$, $q$Pune el palmele pe obrajii voștri: „Reci!” După câteva minute: „Calde!”$q$, $q$O îmbrățișare sub pătură: „Acum e cald.”$q$]::text[], $q$A frecat palmele cu voi sau v-a pus mâinile pe obraji.$q$, $q$Încălzește el mâinile celuilalt părinte.$q$, $q$Jocul „brrr” și „aaah”: tremurați de frig, apoi oftați de cald, iar el vă imită.$q$, $q$Mâinile reci nu se încălzesc pe calorifer sau sub apă fierbinte; doar frecat și îmbrățișat.$q$),
    ($q$s13-2-3-z7-fizic$q$, $q$Plimbare liberă cu haine$q$, array[$q$El dictează direcția pe scurt, îmbrăcat cum e nevoie.$q$, $q$Voi numiți haina doar dacă o arată.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 6, $q$A mers liber câteva minute.$q$, $q$Plimbare liberă îmbrăcat$q$, array[$q$hainele lui de afară$q$, $q$coșul de la ușă$q$]::text[], 8, array[$q$Se îmbracă cu voi, cum a învățat săptămâna asta; aduce el căciula și mănușile din coș.$q$, $q$Afară, el alege direcția; voi mergeți după el.$q$, $q$Numiți doar ce arată el: „Frunză udă.”$q$, $q$Când îi e frig sau obosește: „Hai acasă.”$q$]::text[], $q$A mers liber câteva minute și a ales el direcția.$q$, $q$Aduce acasă un lucru de afară, de exemplu o frunză mare.$q$, $q$La final: „Unde e casa?” Vă duce el înapoi la ușă.$q$, $q$E frig: ieșire de 5–10 minute, verificați des mâinile și nasul. Poarta curții rămâne închisă. Ce adună de jos nu ajunge în gură; la intrare vă spălați pe mâini.$q$),
    ($q$s13-2-3-z7-mental$q$, $q$Carte: haine pe vreme$q$, array[$q$El întoarce pagina.$q$, $q$Arătați o haină din imagine dacă e clar: „Haină.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$carte cu imagini$q$]::text[], 4, $q$A întors pagina sau a privit.$q$, $q$Cartea hainelor lui Cezar$q$, array[$q$cartea lui Cezar, făcută din pozele lui$q$, $q$o carte cartonată din casă$q$]::text[], 8, array[$q$Răsfoiți cartea făcută din pozele lui îmbrăcat: cu căciulă, cu mănuși, cu cizme.$q$, $q$La fiecare pagină: „Uite-l pe Cezar! Arată-mi căciula.”$q$, $q$După ce arată pe poză: „Adu-mi căciula adevărată.” O aduce din coș și o pune lângă poză.$q$, $q$Întoarce el paginile, în ritmul lui.$q$]::text[], $q$A arătat pe poze cel puțin două haine și a pus una adevărată lângă poza ei.$q$, $q$În cartea cartonată din casă: „Arată-mi câinele. Ce face câinele?” Faceți voi „ham-ham”; dacă imită, e un bonus.$q$, $q$Puneți pe jos trei pagini (căciula, mănușile, cizmele) și aduce el din casă fiecare haină lângă poza ei.$q$, $q$Paginile sunt acoperite cu folie și au colțurile rotunjite; inelele sunt mai mari de 3,2 cm sau sunt înlocuite cu o sfoară scurtă, legată strâns.$q$),
    ($q$s13-2-3-z7-resurse$q$, $q$Hainele de afară pe cârlig$q$, array[$q$Agățați haina împreună.$q$, $q$„La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$haină$q$]::text[], 4, $q$A ajutat la agățat.$q$, $q$Coșul de la ușă, pregătit pentru mâine$q$, array[$q$coșul de la ușă$q$, $q$căciula, mănușile și o șosetă rătăcită$q$]::text[], 5, array[$q$Duminică seara, mergeți la coșul de la ușă.$q$, $q$Scoateți totul pe jos: căciula, mănușile și o șosetă pe care ați pus-o voi acolo.$q$, $q$Pune el la loc doar ce e de afară; șoseta o duce în sertar.$q$, $q$„Gata pentru mâine!”$q$]::text[], $q$A pus la loc în coș cel puțin o piesă și a scos ce nu era de acolo, cu ajutor.$q$, $q$Pune mănușile împreună, ca pereche.$q$, $q$Ascundeți o jucărie în coș: o scoate el și o duce la locul ei.$q$, null),
    ($q$s13-2-3-z7-social$q$, $q$Noapte bună$q$, array[$q$„Noapte bună.”$q$, $q$Lumină mică, fără grabă.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A auzit ritualul de noapte.$q$, $q$Noapte bună$q$, array[$q$veioza$q$]::text[], 5, array[$q$„Noapte bună, haine!” Treceți pe la coșul de la ușă.$q$, $q$Lumină mică, fără grabă.$q$, $q$Stinge el veioza, cu mâna voastră peste a lui.$q$, $q$„Noapte bună, Cezar.”$q$]::text[], $q$A făcut cu mâna sau a stins lumina cu voi.$q$, $q$Face „pa” căciulii și cizmelor.$q$, $q$Alege el, dintre două, cartea sau jucăria cu care merge la culcare.$q$, $q$Cablul veiozei e prins și departe de pat; becul nu se atinge, e cald.$q$),
    ($q$s14-2-3-z1-fizic$q$, $q$Zece pași pe hol$q$, array[$q$Mergeți pe hol 8–10 pași împreună.$q$, $q$„Pași. Unu. Doi.” pe scurt.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 5, $q$A făcut câțiva pași pe hol.$q$, $q$Pe drumul de bandă$q$, array[$q$drumul de bandă de pe hol$q$, $q$ursulețul$q$]::text[], 8, array[$q$Lipiți banda pe hol, 3 metri, cu ursulețul la capăt: „Drumul spre urs.”$q$, $q$Mergeți voi întâi pe bandă, pas cu pas.$q$, $q$Merge el, iar voi stați lângă el: „Pas, pas, pas.”$q$, $q$La urs: o îmbrățișare și „Am ajuns!”$q$]::text[], $q$A mers pe bandă sau pe lângă ea până la ursuleț.$q$, $q$Duce ursulețul înapoi la început, tot pe bandă.$q$, $q$Banda face o cotitură; urmează el cotitura.$q$, $q$Banda de hârtie se dezlipește ușor: verificați să nu rămână bucăți pe care să le mestece. Pe hol nu stau covorașe care alunecă.$q$),
    ($q$s14-2-3-z1-mental$q$, $q$Unde merge drumul?$q$, array[$q$Arătați înainte: „Drumul. Acolo.”$q$, $q$Faceți un pas: „Pași.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A privit direcția sau a făcut un pas.$q$, $q$Unde duce drumul?$q$, array[$q$drumul de bandă$q$, $q$ursulețul și o mașinuță$q$]::text[], 5, array[$q$Puneți ursulețul la capătul benzii.$q$, $q$„Unde duce drumul?” Mergeți cu degetul de-a lungul benzii.$q$, $q$Arată el sau merge până la urs.$q$, $q$Mutați ursulețul la celălalt capăt: „Acum unde?”$q$]::text[], $q$A arătat sau a mers spre capătul unde e jucăria, măcar o dată.$q$, $q$Două benzi, cu câte o jucărie la capăt: „Unde e mașina?” Alege el drumul.$q$, $q$„Du mașina la urs.” O împinge pe bandă până la ursuleț.$q$, $q$Mașinuța e mare, fără piese care se desprind. Banda e bine lipită; bucățile desprinse le luați imediat.$q$),
    ($q$s14-2-3-z1-resurse$q$, $q$Pantofii la ușă înainte de pași$q$, array[$q$Luați pantofii împreună.$q$, $q$Puneți-i la ușă: „La loc. La ușă.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$pantofi$q$]::text[], 4, $q$A ajutat cu pantofii.$q$, $q$Cizmele la ușă înainte de drum$q$, array[$q$cizmele lui$q$, $q$preșul de la ușă$q$]::text[], 5, array[$q$„Mergem afară. Unde sunt cizmele?”$q$, $q$Le caută el; le-ați lăsat în camera lui.$q$, $q$Le duce pe preșul de la ușă.$q$, $q$„La ușă. Gata de drum.”$q$]::text[], $q$A găsit cizmele și le-a dus la ușă.$q$, $q$Instrucțiune în doi pași: „Ia căciula din coș și pune-o lângă cizme.”$q$, $q$Vă aduce cizmele voastre, mari și grele; le poate târî.$q$, null),
    ($q$s14-2-3-z1-social$q$, $q$Mergem de mână pe scurt$q$, array[$q$Oferiți mâna: „Mână?”$q$, $q$Mergeți 5 pași, fără forțare.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A ținut mâna sau a mers alături.$q$, $q$Mergem de mână$q$, '{}'::text[], 5, array[$q$Întindeți mâna: „Mână?”$q$, $q$Mergeți împreună pe drumul de bandă sau prin curte.$q$, $q$La capăt schimbați: vă conduce el.$q$, $q$„Mulțumesc că m-ai dus!”$q$]::text[], $q$V-a ținut de mână câțiva pași sau v-a condus el.$q$, $q$Vă duce la un loc ales de el în casă.$q$, $q$Conduce doi oameni deodată: o mână la mama, una la tata.$q$, $q$Afară, poarta curții rămâne închisă și e îmbrăcat după vreme.$q$),
    ($q$s14-2-3-z2-fizic$q$, $q$Pași până la ușă$q$, array[$q$Mergeți împreună până la ușă.$q$, $q$Atingeți ușa: „Ușa. Gata.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 5, $q$A ajuns la ușă.$q$, $q$Pe drum până la ușă$q$, array[$q$drumul de bandă, prelungit până la ușa camerei$q$, $q$o pernă$q$]::text[], 5, array[$q$Prelungiți banda până la ușa camerei.$q$, $q$Pornește el din celălalt capăt al holului.$q$, $q$Merge pe drum până la ușă.$q$, $q$Atinge ușa: „Am ajuns. Ușa!”$q$]::text[], $q$A mers până la ușă și a atins-o.$q$, $q$Merge cu o jucărie în brațe, mai greu pentru echilibru.$q$, $q$O pernă pe drum: o ocolește sau o calcă.$q$, $q$Ușa e fixată, ca să nu se închidă peste degete. Perna e joasă și moale.$q$),
    ($q$s14-2-3-z2-mental$q$, $q$Aproape și departe pe hol$q$, array[$q$Stați aproape de ușă: „Aproape.”$q$, $q$Faceți câțiva pași înapoi: „Departe.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A auzit cuvintele pe scurt.$q$, $q$Aproape și departe$q$, array[$q$mingea moale$q$, $q$drumul de bandă$q$]::text[], 6, array[$q$Puneți mingea lângă el: „Aproape.”$q$, $q$Duceți mingea la capătul holului: „Departe.”$q$, $q$„Adu mingea de departe!” Merge el și o aduce.$q$, $q$Repetați de 2–3 ori, schimbând locurile.$q$]::text[], $q$A adus mingea de la capătul holului când i-ați cerut-o pe cea de departe.$q$, $q$Două mingi, una aproape și una departe: „Adu-o pe cea de departe.”$q$, $q$Pune el mingea departe și vă trimite pe voi după ea.$q$, $q$Mingea e moale și mai mare decât pumnul lui.$q$),
    ($q$s14-2-3-z2-resurse$q$, $q$Cheia / geanta la loc după ușă$q$, array[$q$Luați obiectul de la ușă pe scurt.$q$, $q$Puneți-l la loc: „La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$cheie sau geantă mică$q$]::text[], 4, $q$A ajutat să pună obiectul la loc.$q$, $q$Geanta la loc lângă ușă$q$, array[$q$o geantă mică de pânză, cu baretă scurtă$q$, $q$scaunul de la ușă$q$]::text[], 5, array[$q$Luați geanta: „Mergem? Luăm geanta.”$q$, $q$O duce el până la ușă.$q$, $q$Când vă întoarceți: „Am venit. Geanta la loc.” O pune pe scaunul de la ușă.$q$, $q$Bateți palma.$q$]::text[], $q$A dus geanta la ușă și înapoi la locul ei.$q$, $q$Pune el ceva în geantă înainte de plecare, de exemplu ursulețul.$q$, $q$„Ce luăm la drum?” Alege două lucruri din trei și le pune în geantă.$q$, $q$Geanta nu are baretă lungă care să treacă pe după gât. Cheile rămân la adult.$q$),
    ($q$s14-2-3-z2-social$q$, $q$Batem ușor în ușă împreună$q$, array[$q$Bateți ușor de două ori: „Toc. Toc.”$q$, $q$Zâmbiți: „Ușa.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A bătut sau a privit.$q$, $q$Toc, toc la ușă$q$, '{}'::text[], 5, array[$q$Mergeți la o ușă închisă, cu un părinte în spatele ei.$q$, $q$„Toc, toc!” Bate el.$q$, $q$Părintele întreabă „Cine e?”, deschide și spune: „Cezar!”$q$, $q$Schimbați: el se ascunde, voi bateți.$q$]::text[], $q$A bătut în ușă și a așteptat să se deschidă.$q$, $q$Bate de două ori, ca voi.$q$, $q$Stă el înăuntru și deschide când bateți voi, cu ajutor la clanță.$q$, $q$Degetele departe de balamale; ușa o deschide încet adultul.$q$),
    ($q$s14-2-3-z3-fizic$q$, $q$Pași pe treaptă$q$, array[$q$Urcați sau coborâți o treaptă cu adultul.$q$, $q$„Treaptă. Pas.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 5, $q$A făcut un pas pe treaptă cu ajutor.$q$, $q$Pași pe treaptă$q$, array[$q$treapta joasă$q$]::text[], 6, array[$q$Stați cu el la baza treptei, voi pe partea fără balustradă.$q$, $q$„Sus!” Urcă ținându-se de mâna voastră.$q$, $q$„Jos!” Coboară cu fața spre treaptă sau ținut de mână.$q$, $q$Repetați de 3 ori; arată el cu mâna „sus” sau „jos”.$q$]::text[], $q$A urcat și a coborât de 3 ori, ținut de mână, și a arătat cu mâna în sus sau în jos măcar o dată.$q$, $q$Se ține doar de balustradă; mâna voastră e la spatele lui, fără să-l țină.$q$, $q$Dă el comanda, cu un gest sau un sunet, iar voi o faceți; apoi schimbați rolurile.$q$, $q$Adultul stă la un braț distanță, pe partea de jos. Poarta de siguranță a scării mari e închisă. Desculț sau în papuci care nu alunecă, nu în șosete pe gresie.$q$),
    ($q$s14-2-3-z3-mental$q$, $q$Sus pe treaptă, jos pe treaptă$q$, array[$q$Arătați: „Sus.” pe treaptă.$q$, $q$Arătați: „Jos.” pe treaptă.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A auzit sus și jos la treaptă.$q$, $q$Ursulețul sus, ursulețul jos$q$, array[$q$treapta joasă$q$, $q$ursulețul$q$]::text[], 5, array[$q$Puneți ursulețul jos, lângă treaptă: „Ursul e jos.”$q$, $q$Îl puneți sus pe treaptă: „Ursul e sus.”$q$, $q$„Pune ursul jos!” Îl mută el.$q$, $q$„Acum sus!”$q$]::text[], $q$A mutat ursulețul sus sau jos când i-ați cerut, măcar o dată.$q$, $q$Apoi el: „Tu ești jos. Urcă sus!” Urcă ținut de mână.$q$, $q$Două jucării, una sus și una jos: „Unde e mașina?” Arată el.$q$, $q$Când mută ursulețul, stă pe podea lângă treaptă, nu pe ea. Adultul e aproape.$q$),
    ($q$s14-2-3-z3-resurse$q$, $q$Găleata pe treaptă și la loc$q$, array[$q$Puneți găleata pe treaptă pe scurt.$q$, $q$Luați-o înapoi: „La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$găleată mică$q$]::text[], 4, $q$A ajutat cu găleata.$q$, $q$Găleata pe treaptă și la loc$q$, array[$q$găleata de comori$q$, $q$3 jucării mari$q$]::text[], 5, array[$q$Puneți jucăriile în găleată.$q$, $q$O duce el până la treaptă și o pune sus, stând jos.$q$, $q$O ia înapoi: „La loc.”$q$, $q$Găleata merge în colțul ei.$q$]::text[], $q$A dus găleata la treaptă și a adus-o înapoi.$q$, $q$O urcă și o coboară de pe treaptă de 2–3 ori, stând pe podea.$q$, $q$Golește găleata sus și o umple jos, mutând jucăriile una câte una.$q$, $q$Găleata e ușoară; nu urcă treapta cu găleata în mână.$q$),
    ($q$s14-2-3-z3-social$q$, $q$Ținem mâna pe treaptă$q$, array[$q$Țineți mâna la urcat sau coborât.$q$, $q$„Împreună. Treaptă.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A ținut mâna pe treaptă.$q$, $q$Ținem mâna pe treaptă$q$, array[$q$treapta joasă$q$]::text[], 5, array[$q$Stați amândoi la treaptă.$q$, $q$„Mâna?” Urcați împreună.$q$, $q$Coborâți împreună: „Împreună, jos.”$q$, $q$Schimbați: îi dă mâna celuilalt părinte.$q$]::text[], $q$A cerut sau a primit mâna la treaptă.$q$, $q$Vă întinde el mâna înainte să urce.$q$, $q$Ajută ursulețul să urce: îl ține de lăbuță și îl duce sus.$q$, $q$Doar treapta joasă; poarta de siguranță a scării mari e închisă.$q$),
    ($q$s14-2-3-z4-fizic$q$, $q$Pași până la poartă / gard$q$, array[$q$Ieșiți scurt. Mergeți până la poartă sau gard.$q$, $q$Atingeți: „Poarta. Gata.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 6, $q$A ajuns la poartă sau gard.$q$, $q$Până la poartă, cu opriri$q$, array[$q$pozele drumului: ușa, copacul, poarta$q$, $q$hainele lui de afară$q$]::text[], 10, array[$q$Înainte de ieșire, arătați cele trei poze: „Ușa, copacul, poarta.”$q$, $q$Afară, mergeți până la primul reper și arătați poza lui.$q$, $q$Apoi la copac, apoi la poartă; atinge el fiecare reper.$q$, $q$La poartă: „Am ajuns! Înapoi acasă.”$q$]::text[], $q$A mers până la poartă și a atins cel puțin două repere pe drum.$q$, $q$Ține el pozele și o dă pe cea a reperului următor.$q$, $q$La întoarcere merge în față și vă duce la ușă fără să-i arătați drumul.$q$, $q$E frig: ieșire de 5–10 minute, verificați des mâinile și nasul. Poarta curții rămâne închisă. Fântâna și orice altă apă din curte sunt acoperite sau rămân departe de drum.$q$),
    ($q$s14-2-3-z4-mental$q$, $q$Drumul e scurt$q$, array[$q$Arătați drumul: „Drumul. Scurt.”$q$, $q$Faceți 3–5 pași: „Pași.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A mers pe drumul scurt.$q$, $q$Drumul în poze$q$, array[$q$pozele drumului$q$]::text[], 5, array[$q$Așezați pozele pe jos, în ordinea drumului: ușa, copacul, poarta.$q$, $q$Treceți cu degetul peste ele: „Întâi ușa, apoi copacul, apoi poarta.”$q$, $q$„Unde e poarta?” Arată el.$q$, $q$La fereastră, arătați reperele adevărate.$q$]::text[], $q$A arătat poza cerută, poarta sau copacul, măcar o dată.$q$, $q$După ce vede poza, arată reperul adevărat pe fereastră.$q$, $q$Ascundeți poza copacului sub pernă: o caută el.$q$, $q$Pozele sunt acoperite cu folie și au colțurile rotunjite.$q$),
    ($q$s14-2-3-z4-resurse$q$, $q$Pietricica pe drum și la loc$q$, array[$q$Luați o pietricică de pe drum.$q$, $q$Lăsați-o jos: „La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$1 piatră mică$q$]::text[], 4, $q$A luat și a lăsat piatra.$q$, $q$Piatra mare pe drum$q$, array[$q$o piatră netedă, mai mare decât palma lui$q$, $q$găleata de comori$q$]::text[], 5, array[$q$Alegeți împreună o piatră mare și netedă din curte.$q$, $q$O pune el în găleată: „Grea!”$q$, $q$Duce găleata câțiva pași pe drum.$q$, $q$Pune piatra înapoi la locul ei: „La loc.”$q$]::text[], $q$A cărat piatra câțiva pași, în găleată sau în mâini, și a pus-o la loc.$q$, $q$Două pietre, amândouă mai mari decât palma lui: „Care e mai grea?”$q$, $q$Pune 2–3 pietre mari în rând și le ocolește când merge.$q$, $q$Numai pietre mai mari decât palma lui, fără muchii; pietrele mici din jur le strângeți înainte. Nu se aruncă. După joc vă spălați pe mâini.$q$),
    ($q$s14-2-3-z4-social$q$, $q$Arătăm drumul adultului$q$, array[$q$Arătați înainte: „Uite drumul.”$q$, $q$Stați pe scurt lângă adult.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A participat la arătat.$q$, $q$Îi arătăm drumul cuiva$q$, '{}'::text[], 5, array[$q$Vine celălalt părinte: „Unde e poarta?”$q$, $q$Cezar îl ia de mână și îl duce: în casă la ușă, afară la poartă.$q$, $q$La capăt, părintele spune: „Mulțumesc că m-ai dus!”$q$, $q$Bateți palma.$q$]::text[], $q$A condus un adult până la ușă sau până la poartă.$q$, $q$Ia cu el și ursulețul.$q$, $q$Conduce pe drumul din poze: întâi la copac, apoi la poartă.$q$, $q$Afară, poarta curții rămâne închisă.$q$),
    ($q$s14-2-3-z5-fizic$q$, $q$Alergăm până la poartă$q$, array[$q$Alergați 5–10 pași pe loc plat, ținându-l de mână dacă vrea.$q$, $q$Opriți-vă: „Gata. Pași.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 5, $q$A alergat puțin și s-a oprit.$q$, $q$Alergăm și ne oprim$q$, array[$q$toba din cratiță$q$]::text[], 6, array[$q$Pe loc plat: „Unu, doi, trei, plecăm!” Alergați câțiva pași împreună.$q$, $q$Bateți o dată în cratiță: „Stop!” Vă opriți.$q$, $q$Din nou: „Plecăm!”$q$, $q$La capăt, la poartă sau la capătul holului, bateți palma.$q$]::text[], $q$A alergat câțiva pași și s-a oprit la „stop”, măcar o dată.$q$, $q$Oprire mai lungă: stați ca statuile 2–3 secunde.$q$, $q$Dă el semnalul, bătând în cratiță, iar voi alergați și vă opriți.$q$, $q$Loc plat, fără obstacole; în curte, departe de poartă și de apă. Nu aleargă cu ceva în gură.$q$),
    ($q$s14-2-3-z5-mental$q$, $q$Repede și încet pe pași$q$, array[$q$Faceți 2 pași lenți: „Încet.”$q$, $q$Faceți 2 pași mai rapizi: „Repede.” pe scurt.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A simțit ritmul pe scurt.$q$, $q$Repede și încet pe pași$q$, array[$q$toba din cratiță$q$]::text[], 6, array[$q$Bateți rar: „Încet.” Mergeți amândoi cu pași mari și rari.$q$, $q$Bateți des: „Repede.” Pași mici și repezi.$q$, $q$Toba tace: „Stop!” Vă opriți amândoi.$q$, $q$Repetați de 3–4 ori, în altă ordine.$q$]::text[], $q$Și-a schimbat mersul sau s-a oprit după tobă, măcar o dată, fără să fie ținut de mână.$q$, $q$Fără cuvinte, doar după tobă.$q$, $q$Bate el toba, iar voi mergeți după ritmul lui.$q$, $q$Pe hol nu stau covorașe care alunecă. Lingura rămâne la adult când mergeți, ca să nu ajungă în gură din mers.$q$),
    ($q$s14-2-3-z5-resurse$q$, $q$Pantofii la loc după drum$q$, array[$q$Scoateți pantofii la ușă.$q$, $q$„Pantofi. La loc.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$pantofi$q$]::text[], 4, $q$A ajutat cu pantofii.$q$, $q$Cizmele la loc după drum$q$, array[$q$cizmele lui$q$, $q$preșul de la ușă$q$, $q$coșul de la ușă$q$]::text[], 5, array[$q$La intrare, vă așezați.$q$, $q$Scoate el cizmele, cu ajutor la arici sau la fermoar.$q$, $q$Le duce pe preș, una lângă alta.$q$, $q$Căciula și mănușile merg în coșul de la ușă.$q$]::text[], $q$A dus cizmele pe preș și o piesă în coș.$q$, $q$Înainte, își șterge tălpile pe preș, cu pași pe loc.$q$, $q$Le duce și pe ale voastre.$q$, $q$Noroiul de pe cizme nu ajunge la gură; vă spălați pe mâini după.$q$),
    ($q$s14-2-3-z5-social$q$, $q$Pași pe rând$q$, array[$q$Voi faceți un pas. „Acum tu.”$q$, $q$Așteptați fără grabă.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A făcut un pas pe rând.$q$, $q$Pas eu, pas tu$q$, array[$q$drumul de bandă$q$]::text[], 5, array[$q$Stați la începutul benzii.$q$, $q$Faceți voi un pas: „Eu.”$q$, $q$„Acum tu.” Așteptați pasul lui.$q$, $q$Tot așa, până la capăt.$q$]::text[], $q$A așteptat cel puțin două rânduri și a făcut pasul lui.$q$, $q$Pași de animale pe rând: „Cum merge ursul?” Pași grei. „Cum sare iepurașul?” Sărituri mici. Vă copiază.$q$, $q$E el primul, iar voi îl copiați.$q$, $q$Banda e bine lipită; bucățile desprinse le luați imediat, ca să nu ajungă în gură.$q$),
    ($q$s14-2-3-z6-fizic$q$, $q$Plimbare scurtă pe drum$q$, array[$q$Ieșiți 2–3 minute pe drumul cunoscut.$q$, $q$Mergeți liber. Comentați doar dacă arată ceva.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 6, $q$A mers pe drum câteva minute.$q$, $q$Plimbare cu găleata de comori$q$, array[$q$găleata de comori$q$, $q$hainele lui de afară$q$]::text[], 10, array[$q$Îmbrăcați-vă și luați găleata: „Căutăm comori.”$q$, $q$Pe drumul cunoscut, alege el ce adună: o frunză mare, un con mare și întreg de brad, un băț scurt și gros.$q$, $q$Le pune în găleată, iar voi le numiți: „Frunză. Con.”$q$, $q$Acasă, le așezați pe o tavă și le priviți.$q$]::text[], $q$A adunat cel puțin două lucruri în găleată.$q$, $q$Cereri precise: „Adu-mi o frunză.” Apoi: „Acum un con.”$q$, $q$Acasă sortează comorile: frunzele într-o parte, restul în alta.$q$, $q$E frig: ieșire de 5–10 minute, verificați des mâinile și nasul. Poarta curții rămâne închisă. Fără ciuperci, fructe de pădure sau plante necunoscute; ghindele și pietricelele rămân afară; nimic în gură. Bățul nu are vârf, iar cu el nu se aleargă. După plimbare vă spălați pe mâini.$q$),
    ($q$s14-2-3-z6-mental$q$, $q$Ce vedem pe drum?$q$, array[$q$Arătați un lucru clar: „Copac.” sau „Mașină.”$q$, $q$Stați și priviți 10–20 de secunde.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A privit ceva de pe drum.$q$, $q$Ce vedem pe drum?$q$, array[$q$hainele lui de afară$q$]::text[], 5, array[$q$Pe drum, opriți-vă 10–20 de secunde.$q$, $q$„Unde e pasărea? Arată-mi.” Sau câinele, pisica, mașina: ce se vede.$q$, $q$Numiți și extindeți ce arată: „Da, pasărea zboară.”$q$, $q$„Ce face câinele?” Faceți voi „ham-ham”, „cip-cip” sau „vrum”; dacă imită, e un bonus.$q$]::text[], $q$A arătat ce i-ați cerut (o pasăre, un câine, o mașină) măcar o dată sau a arătat el ceva și s-a uitat apoi la voi.$q$, $q$Două lucruri pe rând: „Arată-mi copacul. Acum mașina.”$q$, $q$Acasă, într-o carte cartonată, arată animalul pe care l-a văzut pe drum: din realitate, în poză.$q$, $q$E frig: ieșire de 5–10 minute, verificați des mâinile și nasul. Poarta curții rămâne închisă.$q$),
    ($q$s14-2-3-z6-resurse$q$, $q$Găleata / jucăria după plimbare$q$, array[$q$Duceți obiectul pe scurt afară dacă vrea.$q$, $q$Apoi: „La loc.” în casă.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$găleată sau jucărie$q$]::text[], 4, $q$A ajutat să pună obiectul la loc.$q$, $q$Comorile la loc$q$, array[$q$găleata de comori$q$, $q$o tavă$q$]::text[], 5, array[$q$Golește el găleata pe tavă.$q$, $q$Comorile frumoase merg pe pervaz sau într-o cutie „de afară”.$q$, $q$Scuturați găleata afară, la ușă.$q$, $q$Găleata merge la locul ei.$q$]::text[], $q$A golit găleata și a dus-o la locul ei.$q$, $q$Alege o comoară care stă pe pervaz.$q$, $q$Ce nu păstrați, frunzele ude, le duce el afară și le pune jos în curte.$q$, $q$După ce atinge comorile vă spălați pe mâini; nimic din ele în gură.$q$),
    ($q$s14-2-3-z6-social$q$, $q$Mergem unul lângă altul$q$, array[$q$Stați lângă el pe drum.$q$, $q$Comentați ce face el, fără a prelua.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A mers cu adultul alături.$q$, $q$Unul lângă altul$q$, array[$q$hainele lui de afară$q$]::text[], 5, array[$q$Mergeți alături, fără să-l țineți de mână.$q$, $q$Spuneți ce face el: „Te-ai oprit. Te uiți la pisică.”$q$, $q$Când pornește el, porniți și voi.$q$, $q$Când se oprește, vă opriți.$q$]::text[], $q$A mers alături câteva minute și s-a uitat după voi.$q$, $q$Vă așteaptă el când rămâneți puțin în urmă.$q$, $q$Jocul umbrei: îl copiați; dacă sare, săriți. Când observă, o face înadins.$q$, $q$Afară, poarta curții rămâne închisă.$q$),
    ($q$s14-2-3-z7-fizic$q$, $q$Plimbare liberă pe drumul scurt$q$, array[$q$El dictează direcția pe scurt.$q$, $q$Voi numiți „pași” / „drum” doar dacă arată.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 6, $q$A mers liber câteva minute.$q$, $q$Plimbare liberă pe drumul nostru$q$, array[$q$hainele lui de afară$q$, $q$coșul de la ușă$q$]::text[], 8, array[$q$Îmbrăcat, aduce el căciula și mănușile din coș.$q$, $q$Afară, el alege direcția.$q$, $q$Dacă trece pe la repere, la copac sau la poartă, le atinge; numiți doar ce arată.$q$, $q$„Hai acasă” când îi e frig sau obosește.$q$]::text[], $q$A mers liber câteva minute și a trecut pe la cel puțin un reper.$q$, $q$Vă duce la reperul lui preferat.$q$, $q$Merge pe marginea unei borduri joase, ținut de mână.$q$, $q$E frig: ieșire de 5–10 minute, verificați des mâinile și nasul. Poarta curții rămâne închisă. Bordura e joasă, iar adultul e lângă el.$q$),
    ($q$s14-2-3-z7-mental$q$, $q$Carte: drum și pași$q$, array[$q$El întoarce pagina.$q$, $q$Arătați un drum sau picioare din imagine dacă e clar: „Pași.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$carte cu imagini$q$]::text[], 4, $q$A întors pagina sau a privit.$q$, $q$Cartea drumului nostru$q$, array[$q$cartea lui Cezar, cu paginile noi ale drumului$q$, $q$o carte cartonată din casă$q$]::text[], 8, array[$q$Adăugați în cartea lui paginile drumului: ușa, copacul, poarta și el pe drum.$q$, $q$Răsfoiți: „Unde e Cezar? Pe drum!”$q$, $q$La fiecare pagină: „Arată-mi poarta. Unde e copacul?” Arată el.$q$, $q$Întoarce el paginile; la final: „Mergem mâine iar?”$q$]::text[], $q$A arătat pe poze cel puțin două repere ale drumului.$q$, $q$Într-o carte cartonată cu animale: „Arată-mi pasărea pe care am văzut-o pe drum.” Faceți împreună „cip-cip”.$q$, $q$Răsfoiți și paginile cu haine: „Ce punem când mergem pe drum?” Arată căciula.$q$, $q$Paginile sunt acoperite cu folie și au colțurile rotunjite; inelele sunt mai mari de 3,2 cm sau sunt înlocuite cu o sfoară scurtă, legată strâns.$q$),
    ($q$s14-2-3-z7-resurse$q$, $q$Pantofii și haina la loc$q$, array[$q$Puneți pantofii și haina la loc.$q$, $q$„La loc. Gata.”$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, array[$q$pantofi$q$, $q$haină$q$]::text[], 4, $q$A ajutat cu pantofii sau haina.$q$, $q$Hainele și cizmele la loc$q$, array[$q$cizmele, căciula și mănușile lui$q$, $q$coșul de la ușă$q$]::text[], 5, array[$q$Duminică seara, verificați ușa: cizmele pe preș, căciula și mănușile în coș.$q$, $q$Lipsește ceva? Caută el prin casă; ați lăsat o mănușă în camera lui.$q$, $q$Duce totul la loc.$q$, $q$„Totul e gata pentru mâine.”$q$]::text[], $q$A găsit și a pus la loc cel puțin o piesă.$q$, $q$Pune și haina pe scaunul de la ușă.$q$, $q$Caută fără indiciu: „Unde e cealaltă mănușă?”$q$, null),
    ($q$s14-2-3-z7-social$q$, $q$Noapte bună$q$, array[$q$„Noapte bună.”$q$, $q$Lumină mică, fără grabă.$q$]::text[], $q$Vârsta 1–2: scurt, fără forțare; el poate refuza.$q$, '{}'::text[], 3, $q$A auzit ritualul de noapte.$q$, $q$Noapte bună$q$, array[$q$veioza$q$]::text[], 5, array[$q$La fereastră: „Noapte bună, drum! Noapte bună, poartă!”$q$, $q$Lumină mică, fără grabă.$q$, $q$Stinge el veioza, cu voi.$q$, $q$„Noapte bună, Cezar.”$q$]::text[], $q$A făcut „pa” la fereastră sau a stins lumina cu voi.$q$, $q$Face „pa” și ursulețului care merge la culcare.$q$, $q$Pune el ursulețul la culcare și îl învelește.$q$, $q$Cablul veiozei e prins și departe de pat; becul nu se atinge, e cald.$q$);

  if (select count(*) from b12_plan) <> 56 then
    raise exception 'B12 S13–S14: planul are % rânduri, așteptam 56', (select count(*) from b12_plan);
  end if;

  if to_regclass('public.backup_20261117_b12_s13s14') is null then
    create table public.backup_20261117_b12_s13s14 as
    select * from public.activities
    where banda = '1-2' and saptamana between 13 and 14;
  end if;
  alter table public.backup_20261117_b12_s13s14 enable row level security;
  revoke all on public.backup_20261117_b12_s13s14 from public, anon, authenticated;

  if exists (
    select 1
    from public.backup_20261117_b12_s13s14 as snap
    full join b12_plan as p on p.id = snap.id
    where p.id is null or snap.id is null or snap.banda is distinct from '1-2'
      or snap.saptamana not between 13 and 14
  ) then
    raise exception 'B12 S13–S14: backup-ul nu conține exact cele 56 id-uri din banda 1–2, S13–S14';
  end if;

  for plan in select * from b12_plan order by id loop
    select * into cur from public.backup_20261117_b12_s13s14 where id = plan.id;
    if cur.titlu is distinct from plan.old_titlu or cur.pasi is distinct from plan.old_pasi
       or cur.nota is distinct from plan.old_nota or cur.materiale is distinct from plan.old_materiale
       or cur.durata_min is distinct from plan.old_durata or cur.gata_cand is distinct from plan.old_gata then
      raise exception 'B12 S13–S14: backup-ul pentru % nu e cel din 17.11.2026', plan.id;
    end if;

    select * into cur from public.activities where id = plan.id and banda = '1-2';
    if not found then
      raise exception 'B12 S13–S14: id lipsă din banda 1–2: %', plan.id;
    end if;

    if cur.titlu = plan.titlu and cur.pasi = plan.pasi and cur.materiale = plan.materiale
       and cur.durata_min = plan.durata_min and cur.gata_cand = plan.gata_cand
       and cur.pas_in_plus is not distinct from plan.pas_in_plus
       and cur.provocare is not distinct from plan.provocare
       and cur.siguranta is not distinct from plan.siguranta
       and cur.nota is null then
      skipped_count := skipped_count + 1;
      continue;
    end if;

    if exists (select 1 from public.completions c where c.activity_id = plan.id) then
      raise exception 'B12 S13–S14: % are deja bife; nu schimbăm textul sub ele', plan.id;
    end if;

    update public.activities
    set titlu = plan.titlu,
        materiale = plan.materiale,
        durata_min = plan.durata_min,
        pasi = plan.pasi,
        gata_cand = plan.gata_cand,
        pas_in_plus = plan.pas_in_plus,
        provocare = plan.provocare,
        siguranta = plan.siguranta,
        nota = null
    where id = plan.id
      and banda = '1-2'
      and titlu = plan.old_titlu
      and pasi = plan.old_pasi
      and nota is not distinct from plan.old_nota
      and materiale = plan.old_materiale
      and durata_min = plan.old_durata
      and gata_cand = plan.old_gata;
    get diagnostics touched = row_count;
    if touched <> 1 then
      raise exception 'B12 S13–S14: % nu are textul vechi din backup (rânduri %)', plan.id, touched;
    end if;
    updated_count := updated_count + 1;
  end loop;

  if updated_count + skipped_count <> 56 then
    raise exception 'B12 S13–S14: % actualizate + % deja noi, așteptam 56', updated_count, skipped_count;
  end if;
  if updated_count not in (0, 56) then
    raise exception 'B12 S13–S14: doar % din 56 erau de actualizat; stare amestecată', updated_count;
  end if;

